// Extract and validate chat input from webhook
const body = $json.body || $json;
const chatInput = body.chatInput || body.message;
const sessionId = body.sessionId || `session-${Date.now()}`;
const metadata = body.metadata || {};

// Validate required fields
if (!chatInput) {
  throw new Error('chatInput is required');
}

if (!metadata.customerId) {
  throw new Error('customerId is required in metadata');
}

// Extract customer information
const customerId = metadata.customerId;
const widgetId = metadata.widgetId || 'default';
const companyName = metadata.companyName || '';

// Prepare for vector search
return [{
  json: {
    chatInput,
    sessionId,
    customerId,
    widgetId,
    companyName,
    metadata,
    timestamp: new Date().toISOString(),
    // Chat context for webhook response
    isWebhookChat: true,
    responseFormat: 'json'
  }
}];

