// Build RAG context from search results
const searchResults = $json;
const chatData = $('Extract Webhook Data').item(0).json;
const embeddingData = $('Generate Query Embedding').item(0).json;

// Process search results
let contextText = '';
let sourceCount = 0;
let hasRelevantContent = false;

if (searchResults && Array.isArray(searchResults) && searchResults.length > 0) {
  sourceCount = searchResults.length;
  hasRelevantContent = true;

  // Build context from search results
  const contexts = searchResults.map(result => {
    const similarity = Math.round((result.similarity || 0) * 100);
    return `[Kaynak ${similarity}% benzerlik]: ${result.content}`;
  });

  contextText = contexts.join('\n\n');
} else {
  contextText = 'Belirli bir kaynak bulunamadı. Genel bilgilerimle yanıtlayacağım.';
}

// Prepare context for AI
const systemPrompt = `Sen ${chatData.companyName || 'şirketin'} müşteri hizmetleri asistanısın. Türkçe yanıt ver.

Mevcut bilgiler:
${contextText}

Kullanıcı sorusu: ${chatData.chatInput}

Yanıtın:
- Türkçe olmalı
- Dostane ve profesyonel ton kullan
- Mevcut bilgilere dayalı yanıt ver
- Eğer bilgi yoksa, nazikçe belirt`;

return [{
  json: {
    systemPrompt,
    userQuery: chatData.chatInput,
    contextText,
    hasRelevantContent,
    sourceCount,
    searchResultCount: sourceCount,
    customerId: chatData.customerId,
    widgetId: chatData.widgetId,
    sessionId: chatData.sessionId,
    timestamp: chatData.timestamp,
    tokensUsed: embeddingData.usage?.total_tokens || 0
  }
}];

// Format final webhook response
const aiResponse = $json;
const contextData = $('Build RAG Context').item(0).json;
const chatData = $('Extract Webhook Data').item(0).json;

// Extract AI response text
const responseText = aiResponse.choices?.[0]?.message?.content || 'Üzgünüm, yanıt oluşturamadım.';

// Generate follow-up prompts based on context
const followUpPrompts = [];
if (contextData.hasRelevantContent) {
  followUpPrompts.push(
    'Bu konuda daha detaylı bilgi alabilir miyim?',
    'Başka hangi konularda yardımcı olabilirsiniz?',
    'Bu bilgiyle ilgili örnek verebilir misiniz?'
  );
} else {
  followUpPrompts.push(
    'Başka bir konuda yardım edebilir misiniz?',
    'Size hangi konularda soru sorabilirim?',
    'Daha spesifik bir soru sorabilir miyim?'
  );
}

// Prepare webhook response (ChatTrigger format compatible)
const webhookResponse = {
  output: responseText,
  followUpPrompts: followUpPrompts,
  metadata: {
    sessionId: chatData.sessionId,
    customerId: chatData.customerId,
    widgetId: chatData.widgetId,
    hasRelevantContent: contextData.hasRelevantContent,
    sourceCount: contextData.sourceCount,
    responseTime: Date.now() - new Date(chatData.timestamp).getTime(),
    tokensUsed: (contextData.tokensUsed || 0) + (aiResponse.usage?.total_tokens || 0),
    timestamp: new Date().toISOString(),
    // Webhook specific
    responseType: 'webhook-chat',
    success: true
  }
};

return [{ json: webhookResponse }];
